#!/usr/bin/env bash
# wake-claude.sh — start a headless Claude Code turn for one handoff.
# Generated by `install.sh --target claude`.
#
#   wake-claude.sh "<handoff>"            # a fresh headless turn
#   wake-claude.sh "<handoff>" <sid>      # resume session <sid>
#
# A worker must run in the card's project directory, and only this agent-local
# glue can resolve it. Inputs (set by the supervisor):
#   TP_PROJECT        the card's board project identity
#   TP_PROJECTS_JSON  the local project map (default: beside the installed skill)
#   TP_NODE           node used to resolve it (default: `node` on PATH)
# If the directory cannot be resolved, exit 3 without starting a worker — the
# wrong checkout is worse than no wake.
#
# Do not default to bypassing permissions (`--dangerously-skip-permissions`).
# Run under --permission-mode/--allowedTools or a sandbox; a bypass needs written
# authorization, documented here.
set -eu

prompt="${1:-}"
sid="${2:-}"

if [ -z "$prompt" ]; then
  echo "wake-claude: a handoff prompt is required" >&2
  exit 2
fi

projects_json="${TP_PROJECTS_JSON:-$(dirname "$0")/../skills/meerkat-taskpanel/projects.json}"
if ! cwd="$("${TP_NODE:-node}" "{{LOOP}}/scripts/wake-cwd.mjs" --project "${TP_PROJECT:-}" --projects-json "$projects_json")"; then
  echo "wake-claude: refusing to wake a worker without a target directory" >&2
  exit 3
fi
# `if !` cannot catch an empty $cwd: `cd ""` succeeds in bash and would run the
# worker in the caller's directory. The absolute-path test covers empty and relative.
case "$cwd" in
  /*) ;;
  *) echo "wake-claude: refusing to wake a worker without a target directory" >&2; exit 3 ;;
esac
cd "$cwd"
echo "wake-claude: working directory $cwd" >&2

# Full tool access is an opt-in of the *resident* session pool (`--session`),
# where the operator records an authorization in the agent config. This legacy
# one-shot glue stays inside the no-default-bypass rule: it never adds one.
if [ -n "$sid" ]; then
  exec claude -p "$prompt" --resume "$sid"
fi

exec claude -p "$prompt"
